/* «Что если»: подбор параметра, таблица подстановки, сценарии и поиск решения (линейные и целочисленные модели —
   симплекс-методом и ветвями и границами, нелинейные — спуском со штрафами). Модель книги считается прогонами
   «книга.чтоЕсли» — книга не меняется, пока человек сам не нажмёт «Записать». Нашлось не точно — так и пишем. */
/* ===== Поле на клетках листа: общий кусок игр магазина =====
   Строки и столбцы здесь — С НУЛЯ (r, c); адреса A1 считаются отсюда же.
   ячейка(строка, столбец) API плагина считает с единицы — поэтому везде «+ 1». */
const БУКВА = c => { let s = '', n = c + 1; while(n > 0){ const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = (n - 1 - m) / 26; } return s; };
const АДРЕС = (r, c) => БУКВА(c) + (r + 1);
const ОБЛАСТЬ = (r1, c1, r2, c2) => АДРЕС(r1, c1) + ':' + АДРЕС(r2, c2);
const клетка = (r, c) => ячейка(r + 1, c + 1);
/* Квадратные клетки: ширина столбца в знаках (знак — 7 точек), высота строки в пунктах (×4/3 точки). */
function клеткиКвадратом(r1, c1, r2, c2, точек){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(точек / 7);
  о.SetRowHeight(точек * 0.75);
}
/* Вернуть области обычные размеры клеток (столбец 92 точки, строка 24 точки = 18 пунктов). */
function обычныеРазмеры(r1, c1, r2, c2){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(92 / 7);
  о.SetRowHeight(18);
}
/* Ширина одного столбца и высота одной строки в точках экрана. */
function ширинаСтолбца(c, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c)).SetColumnWidth(точек / 7); }
function высотаСтроки(r, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r, 0, r, 0)).SetRowHeight(точек * 0.75); }
/* Приложение запоминает смещения строк и не сбрасывает их, когда плагин меняет высоты строк:
   после этого щелчок мыши попадает не в ту клетку. Пустая запись в далёкую пустую строку
   растит сетку листа, и смещения пересчитываются. Звать после смены высот. */
async function обновитьВысоты(){
  /* каждый раз — строка дальше прежней: сетка растёт, только если запись за её краем */
  let n = 0; try { n = +лист().память('высоты-шаг') || 0; } catch(e){}
  for(let k = n + 1; k <= n + 40; k++){
    const r = 5999 + k;
    let v = null;
    try { v = await клетка(r, 0).прочитать(); } catch(e){ continue; }
    if(v === null || v === undefined || v === ''){
      клетка(r, 0).значение = null;
      try { лист().запомнить('высоты-шаг', k); } catch(e){}
      return true;
    }
  }
  return false;
}
/* Курсор — на «стоянку» рядом с полем. Тогда повторный щелчок по той же клетке
   снова сменит выделение, и плагин получит событие: иначе второй щелчок молчал бы. */
function наСтоянку(r, c){ клетка(r, c).выделить(); }
/* Пуста ли область листа: игра не должна молча затирать чужие данные. */
async function областьПуста(r1, c1, r2, c2){
  const строки = await диапазон(ОБЛАСТЬ(r1, c1, r2, c2)).прочитать();
  for(const ряд of строки || []) for(const v of ряд || []) if(v !== null && v !== undefined && v !== '') return false;
  return true;
}
/* Рамка: все четыре стороны одним видом. */
const РАМКА = (вид, цвет) => ({в: {вид, цвет}, н: {вид, цвет}, л: {вид, цвет}, п: {вид, цвет}});
/* Число со словом в нужной форме: число(5, 'выстрел', 'выстрела', 'выстрелов') → «5 выстрелов». */
function число(n, одна, две, пять){ const a = Math.abs(n) % 100, b = a % 10;
  return n + ' ' + (a > 10 && a < 20 ? пять : b === 1 ? одна : b >= 2 && b <= 4 ? две : пять); }
/* Время «м:сс». */
const ВРЕМЯ = с => Math.floor(с / 60) + ':' + String(Math.floor(с % 60)).padStart(2, '0');
/* Повод события — клетка с нуля и на нужном ли листе. */
function гдеЩелчок(п, лист){
  if(!п || !п.адрес || (лист && п.лист !== лист)) return null;
  if(п.клеток > 1) return null;                     /* протянули мышью область — это не ход */
  return {r: п.строка - 1, c: п.столбец - 1};
}
/* Защита от «правой кнопки»: правый щелчок сначала зовёт меню, а через 150 мс
   приходит выделение той же клетки. Такой выбор ходом не считаем. */
let последнееМеню = {адрес: '', t: 0};
const этоПослеМеню = п => п && п.адрес === последнееМеню.адрес && Date.now() - последнееМеню.t < 1500;
/* ===== конец общего куска ===== */
/* Оформление области по клеткам. Api GetRange(…).SetNumberFormat и другие оформления области из потока
   задевают только ту часть, что была занята при запуске потока, — свежие строки остаются без оформления.
   л — лист плагина: лист(имя) или черновик; строки и столбцы — с нуля. */
function оформитьОбласть(л, r1, c1, r2, c2, стиль){
  if((r2 - r1 + 1) * (c2 - c1 + 1) > 300000) return false;
  for(let r = r1; r <= r2; r++) for(let c = c1; c <= c2; c++) л.ячейка(r + 1, c + 1).стиль = стиль;
  return true;
}
/* ===== Линейное и целочисленное программирование: двухфазный симплекс-метод и ветви и границы ===== */
const ЛП = (() => {
  const EPS = 1e-9;
  /* задача: {c: [n], max: true|false, строки: [{a: [n], знак: '<='|'>='|'=', b}], свободные: [индексы переменных без x ≥ 0]}
     ответ: {статус: 'оптимум'|'несовместна'|'неограничена'|'предел', x, цель, итераций} */
  function решить(з, предел = 20000){
    const n0 = з.c.length;
    /* свободная переменная = x⁺ − x⁻ */
    const своб = new Set(з.свободные || []);
    const карта = []; let n = 0;
    for(let j = 0; j < n0; j++){ карта.push([n, своб.has(j) ? n + 1 : -1]); n += своб.has(j) ? 2 : 1; }
    const раз = v => { const out = new Array(n).fill(0); for(let j = 0; j < n0; j++){ out[карта[j][0]] = v[j]; if(карта[j][1] >= 0) out[карта[j][1]] = -v[j]; } return out; };
    const строки = з.строки.map(r => { let a = раз(r.a), b = r.b, знак = r.знак; if(b < 0){ a = a.map(x => -x); b = -b; знак = знак === '<=' ? '>=' : знак === '>=' ? '<=' : '='; } return {a, b, знак}; });
    const m = строки.length;
    const nСлак = строки.filter(r => r.знак !== '=').length, nИск = строки.filter(r => r.знак !== '<=').length;
    const N = n + nСлак + nИск;
    const T = []; const базис = new Array(m);
    let s = n, ар = n + nСлак;
    const иск = [];
    строки.forEach((r, i) => {
      const ряд = new Float64Array(N + 1);
      for(let j = 0; j < n; j++) ряд[j] = r.a[j];
      if(r.знак === '<='){ ряд[s] = 1; базис[i] = s; s++; }
      else if(r.знак === '>='){ ряд[s] = -1; s++; ряд[ар] = 1; базис[i] = ар; иск.push(ар); ар++; }
      else { ряд[ар] = 1; базис[i] = ар; иск.push(ар); ар++; }
      ряд[N] = r.b;
      T.push(ряд);
    });
    let итераций = 0;
    function шагать(цель, запрет){
      /* цель — коэффициенты максимизации по всем N; строка приведённых стоимостей */
      const z = new Float64Array(N + 1);
      for(let j = 0; j <= N; j++){ let v = j < N ? -(цель[j] || 0) : 0; for(let i = 0; i < m; i++){ const cb = цель[базис[i]] || 0; if(cb) v += cb * T[i][j]; } z[j] = v; }
      for(;;){
        if(++итераций > предел) return 'предел';
        let вход = -1;
        for(let j = 0; j < N; j++){ if(запрет && запрет(j)) continue; if(z[j] < -EPS){ вход = j; break; } }        /* правило Бленда */
        if(вход < 0) return 'оптимум';
        let выход = -1, лучш = Infinity;
        for(let i = 0; i < m; i++){ const a = T[i][вход]; if(a > EPS){ const t = T[i][N] / a; if(t < лучш - EPS || (Math.abs(t - лучш) <= EPS && базис[i] < базис[выход])){ лучш = t; выход = i; } } }
        if(выход < 0) return 'неограничена';
        повернуть(выход, вход, z);
      }
    }
    function повернуть(р, к, z){
      const ряд = T[р], p = ряд[к];
      for(let j = 0; j <= N; j++) ряд[j] /= p;
      for(let i = 0; i < m; i++){ if(i === р) continue; const f = T[i][к]; if(Math.abs(f) > 1e-15){ const r2 = T[i]; for(let j = 0; j <= N; j++) r2[j] -= f * ряд[j]; } }
      if(z){ const f = z[к]; if(Math.abs(f) > 1e-15) for(let j = 0; j <= N; j++) z[j] -= f * ряд[j]; }
      базис[р] = к;
    }
    /* фаза 1: максимизируем −Σ искусственных */
    if(иск.length){
      const ц1 = new Float64Array(N); for(const j of иск) ц1[j] = -1;
      const ст = шагать(ц1, null);
      if(ст === 'предел') return {статус: 'предел', итераций};
      let сумма = 0; for(let i = 0; i < m; i++) if(иск.includes(базис[i])) сумма += T[i][N];
      if(сумма > 1e-7 * Math.max(1, ...строки.map(r => Math.abs(r.b)))) return {статус: 'несовместна', итераций};
      /* искусственные — вон из базиса */
      for(let i = 0; i < m; i++){
        if(!иск.includes(базис[i])) continue;
        let к = -1; for(let j = 0; j < n + nСлак; j++) if(Math.abs(T[i][j]) > 1e-9){ к = j; break; }
        if(к >= 0) повернуть(i, к, null);
      }
    }
    /* фаза 2 */
    const ц = new Float64Array(N);
    const c = раз(з.c); for(let j = 0; j < n; j++) ц[j] = з.max === false ? -c[j] : c[j];
    const искМн = new Set(иск);
    const ст = шагать(ц, j => искМн.has(j));
    if(ст !== 'оптимум') return {статус: ст, итераций};
    const xx = new Array(N).fill(0);
    for(let i = 0; i < m; i++) xx[базис[i]] = T[i][N];
    const x = []; for(let j = 0; j < n0; j++) x.push(xx[карта[j][0]] - (карта[j][1] >= 0 ? xx[карта[j][1]] : 0));
    const цель = з.c.reduce((s2, cj, j) => s2 + cj * x[j], 0);
    return {статус: 'оптимум', x, цель, итераций};
  }
  /* ветви и границы: целые — индексы целочисленных переменных */
  function целочисленно(з, целые, о){
    о = о || {};
    const до = Date.now() + (о.время || 20000), узловМакс = о.узлов || 50000;
    let лучшее = null, узлов = 0, остановлено = false;
    const лучше = (a, b) => з.max === false ? a < b - 1e-9 : a > b + 1e-9;
    const стек = [[]];
    const корень = решить(з);
    if(корень.статус !== 'оптимум') return Object.assign({}, корень, {узлов: 1});
    let граница = корень.цель;
    while(стек.length){
      if(++узлов > узловМакс || Date.now() > до){ остановлено = true; break; }
      const доп = стек.pop();
      const р = решить(Object.assign({}, з, {строки: з.строки.concat(доп)}));
      if(р.статус !== 'оптимум') continue;
      if(лучшее && !лучше(р.цель, лучшее.цель)) continue;
      /* самая дробная переменная */
      let k = -1, дробь = 0;
      for(const j of целые){ const f = р.x[j] - Math.floor(р.x[j] + 1e-9); const d = Math.min(f, 1 - f); if(d > 1e-6 && d > дробь){ дробь = d; k = j; } }
      if(k < 0){ лучшее = {x: р.x.map((v, j) => целые.includes(j) ? Math.round(v) : v), цель: р.цель}; continue; }
      const e = з.c.map((_, j) => j === k ? 1 : 0), v = р.x[k];
      /* сначала ветвь ближе к дробному значению */
      const вниз = доп.concat([{a: e, знак: '<=', b: Math.floor(v)}]), вверх = доп.concat([{a: e, знак: '>=', b: Math.ceil(v)}]);
      if(v - Math.floor(v) < 0.5){ стек.push(вверх); стек.push(вниз); } else { стек.push(вниз); стек.push(вверх); }
    }
    if(!лучшее) return {статус: остановлено ? 'предел' : 'несовместна', узлов, граница};
    return {статус: остановлено ? 'предел' : 'оптимум', x: лучшее.x, цель: лучшее.цель, узлов, граница};
  }
  return {решить, целочисленно};
})();
/* ===== конец куска «Линейное программирование» ===== */
const числом = v => typeof v === 'number' && isFinite(v) ? v : (typeof v === 'boolean' ? +v : NaN);
const ошибка = v => v && typeof v === 'object' && v.e;
const чсл = (v, зн = 6) => typeof v === 'number' && isFinite(v) ? (Math.abs(v) >= 1e9 || (Math.abs(v) < 1e-4 && v) ? v.toExponential(4).replace('.', ',') : v.toLocaleString('ru-RU', {maximumFractionDigits: зн})) : String(ошибка(v) || v);
const текстЧисло = т => { const s = String(т).trim().replace(/\s/g, '').replace(',', '.'); return s === '' ? NaN : +s; };

/* ---------- адреса ---------- */
function разобратьАдрес(т){
  const s = String(т || '').trim().replace(/\$/g, '');
  const m = s.match(/^(?:'?([^'!]+)'?!)?([A-Z]{1,3})(\d+)(?::([A-Z]{1,3})(\d+))?$/i);
  if(!m) throw new Error('Не понял адрес «' + т + '»: пишите как B2, B2:D5 или Лист2!B2');
  const кол = б => [...б.toUpperCase()].reduce((a, ch) => a * 26 + ch.charCodeAt(0) - 64, 0) - 1;
  const r1 = +m[3] - 1, c1 = кол(m[2]), r2 = m[5] ? +m[5] - 1 : r1, c2 = m[4] ? кол(m[4]) : c1;
  return {лист: m[1] || null, r1: Math.min(r1, r2), c1: Math.min(c1, c2), r2: Math.max(r1, r2), c2: Math.max(c1, c2)};
}
const сЛистом = (а, адрес) => а.лист ? (/[\s!']/.test(а.лист) ? "'" + а.лист + "'" : а.лист) + '!' + адрес : адрес;
/* «B2:D2, F5» → список адресов клеток */
function клетки(т){
  const out = [];
  for(const кус of String(т || '').split(/[;,]\s*(?=[A-Za-z'А-Яа-я])/).map(x => x.trim()).filter(Boolean)){
    const а = разобратьАдрес(кус);
    if((а.r2 - а.r1 + 1) * (а.c2 - а.c1 + 1) > 5000) throw new Error('Слишком большая область «' + кус + '» — до 5000 клеток');
    for(let r = а.r1; r <= а.r2; r++) for(let c = а.c1; c <= а.c2; c++) out.push(сЛистом(а, АДРЕС(r, c)));
  }
  return out;
}
function одна(т, что){ const к = клетки(т); if(к.length !== 1) throw new Error(что + ': нужна одна клетка, а не «' + т + '»'); return к[0]; }
function значение(адрес){
  const а = разобратьАдрес(адрес);
  return (а.лист ? лист(а.лист) : лист()).ячейка(а.r1 + 1, а.c1 + 1).значение;
}
function формула(адрес){ const а = разобратьАдрес(адрес); return (а.лист ? лист(а.лист) : лист()).ячейка(а.r1 + 1, а.c1 + 1).формула; }
/* подпись клетки: текст слева в строке и сверху в столбце; «полная» — обе («Выпуск · Столы») */
function подпись(адрес, полная){
  const а = разобратьАдрес(адрес), л = а.лист ? лист(а.лист) : лист();
  /* до первой непустой клетки: текст — подпись, число — подписи нет */
  const искать = (шаги) => { for(const [r, c] of шаги){ const v = л.ячейка(r + 1, c + 1).значение; if(v === null || v === undefined || v === '') continue; return typeof v === 'string' && v.length < 60 ? v.trim().replace(/:$/, '') : null; } return null; };
  const слева = искать(Array.from({length: Math.min(6, а.c1)}, (_, k) => [а.r1, а.c1 - 1 - k]));
  const сверху = искать(Array.from({length: Math.min(6, а.r1)}, (_, k) => [а.r1 - 1 - k, а.c1]));
  if(полная && слева && сверху) return слева + ' · ' + сверху;
  return слева || сверху || адрес;
}
function формат(адрес){ try { const а = разобратьАдрес(адрес); const ф = (а.лист ? Api.GetSheet(а.лист) : Api.GetActiveSheet()).GetRange(АДРЕС(а.r1, а.c1)).GetNumberFormat(); return ф && ф !== 'General' ? ф : null; } catch(e){ return null; } }
const выделенное = () => { const в = книга.выделение; if(!в) throw new Error('Выделите клетку'); return в.область.replace(/^([A-Z]+\d+):\1$/, '$1'); };
/* ряды на лист: значения пачкой, «=…» — формулами */
function выложитьРяды(л, r0, c0, строки){
  const ш = Math.max(...строки.map(р => р.length));
  const знач = строки.map(р => Array.from({length: ш}, (_, j) => { const v = р[j]; return typeof v === 'string' && v[0] === '=' ? null : (v === undefined ? null : v); }));
  л.диапазон(ОБЛАСТЬ(r0, c0, r0 + строки.length - 1, c0 + ш - 1)).записать(знач);
  строки.forEach((р, i) => р.forEach((v, j) => { if(typeof v === 'string' && v[0] === '=') л.ячейка(r0 + i + 1, c0 + j + 1).формула = v.slice(1); }));
}
async function прогон(наборы, цели){
  const out = [];
  for(let i = 0; i < наборы.length; i += 50000) out.push(...await книга.чтоЕсли({наборы: наборы.slice(i, i + 50000), цели}));
  return out;
}

/* ================= подбор параметра ================= */
let найдено = null;
async function _Подобрать(){
  const п = параметры({});
  const цель = одна(п.цель, 'Цель'), пар = одна(п.параметр, 'Изменяемая клетка'), нужно = текстЧисло(п.значение);
  if(!isFinite(нужно)){ панель.поле('итогПодбора', [{текст: 'Укажите, какое значение нужно получить', цвет: '#c92a2a'}]); return; }
  if(!формула(цель)){ панель.поле('итогПодбора', [{текст: 'В клетке ' + цель + ' нет формулы — подбирать нечего', цвет: '#c92a2a'}]); return; }
  if(формула(пар)){ панель.поле('итогПодбора', [{текст: 'В изменяемой клетке ' + пар + ' формула — нужна клетка со значением', цвет: '#c92a2a'}]); return; }
  const x0 = числом(значение(пар)) || 0;
  const от = текстЧисло(п.от), до = текстЧисло(п.до);
  const f = async xs => (await прогон(xs.map(x => ({[пар]: x})), [цель])).map(r => числом(r[0]) - нужно);
  let xs;
  if(isFinite(от) && isFinite(до) && до > от){ xs = []; for(let i = 0; i <= 200; i++) xs.push(от + (до - от) * i / 200); }
  else {
    const s = Math.max(Math.abs(x0), 1) * 1e-4; xs = [x0];
    for(let k = 0; k <= 64; k++){ const d = s * Math.pow(2, k / 1.5); xs.push(x0 + d, x0 - d); }
    xs.sort((a, b) => a - b);
