  }
  const конечные = g.filter(isFinite);
  if(!пара){
    const лучшее = xs[g.map(Math.abs).indexOf(Math.min(...g.filter(isFinite).map(Math.abs)))];
    найдено = null;
    панель.поле('итогПодбора', [{текст: 'Решение не найдено. ', жирный: true, цвет: '#c92a2a'},
      {текст: конечные.length ? 'При ' + пар + ' от ' + чсл(xs[0]) + ' до ' + чсл(xs[xs.length - 1]) + ' цель ' + цель + ' принимает значения от ' + чсл(Math.min(...конечные) + нужно) + ' до ' + чсл(Math.max(...конечные) + нужно) + ' и ' + чсл(нужно) + ' не достигает. Ближе всего — при ' + пар + ' = ' + чсл(лучшее) + '.' : 'Цель при всех пробных значениях даёт ошибку.'}]);
    return;
  }
  /* сужаем пару пачками по 33 точки */
  let [a, b] = пара;
  for(let раунд = 0; раунд < 14 && b - a > 1e-13 * Math.max(1, Math.abs(a)); раунд++){
    const точки = []; for(let i = 0; i <= 32; i++) точки.push(a + (b - a) * i / 32);
