    for(let i = 0; i < 32; i++){ if(gg[i] === 0){ a = b = точки[i]; break; } if(isFinite(gg[i]) && isFinite(gg[i + 1]) && Math.sign(gg[i]) !== Math.sign(gg[i + 1])){ j = i; break; } }
