  найдено = {пар, x, цель, значение: (Math.abs(ga) <= Math.abs(gb) ? ga : gb) + нужно};
  панель.поле('итогПодбора', точно
    ? [{текст: 'Найдено: ', жирный: true, цвет: '#2b8a3e'}, {текст: пар + ' = ' + чсл(x, 10) + ', цель ' + цель + ' = ' + чсл(найдено.значение, 10) + '. Книга не менялась — «Записать найденное», чтобы оставить.'}]
    : [{текст: 'Точного решения нет: ', жирный: true, цвет: '#c92a2a'}, {текст: 'на отрезке около ' + пар + ' = ' + чсл(x) + ' цель меняет знак скачком (разрыв): ' + чсл(ga + нужно) + ' и ' + чсл(gb + нужно) + '. Ничего не записано.'}]);
