/* ================= таблица подстановки ================= */
async function значенияИз(т){
  const s = String(т || '').trim();
  if(!s) throw new Error('Перечислите значения: «0,1; 0,12; 0,15», «0,05…0,2 шаг 0,01» или адрес области с ними');
  const диап = s.match(/^(-?[\d\s.,]+?)\s*(?:…|\.\.\.?|до)\s*(-?[\d\s.,]+?)\s*(?:шаг|,\s*шаг)\s*(-?[\d\s.,]+)$/i);
  if(диап){
    const a = текстЧисло(диап[1]), b = текстЧисло(диап[2]), h = Math.abs(текстЧисло(диап[3]));
    if(!(h > 0)) throw new Error('Шаг должен быть больше нуля');
    const n = Math.floor((b - a) / h + 1e-9) + 1; if(n > 5000) throw new Error('Больше 5000 значений — увеличьте шаг');
    return Array.from({length: Math.max(1, n)}, (_, i) => +(a + i * h).toPrecision(12));
  }
  if(/^'?[^;]*!?[A-Z]{1,3}\d+(:[A-Z]{1,3}\d+)?$/i.test(s.replace(/\$/g, ''))){
    const а = разобратьАдрес(s), л = а.лист ? лист(а.лист) : лист();
    const д = await л.прочитать(ОБЛАСТЬ(а.r1, а.c1, а.r2, а.c2));
    return д.flat().filter(v => typeof v === 'number');
  }
  return s.split(/;\s*/).map(текстЧисло).filter(isFinite);
}
async function _Построить(){
