  const вход1 = одна(п.вход1, 'Клетка параметра'), з1 = await значенияИз(п.значения1);
  const вход2 = два ? одна(п.вход2, 'Клетка второго параметра') : null, з2 = два ? await значенияИз(п.значения2) : null;
  const цели = два ? [одна(п.цели, 'Цель')] : клетки(п.цели);
