    n = з1.length;
  } else {
    const наборы = []; for(const a of з1) for(const b of з2) наборы.push({[опр.вход1]: a, [опр.вход2]: b});
    const р = await прогон(наборы, цели);
    строки = [[подпись(цели[0]) + ' ↓' + подпись(опр.вход1) + ' →' + подпись(опр.вход2)].concat(з2)];
    з1.forEach((a, i) => строки.push([a].concat(з2.map((_, j) => { const v = р[i * з2.length + j][0]; return ошибка(v) ? String(ошибка(v)) : v; }))));
    n = наборы.length;
  }
  const r2 = r0 + строки.length - 1, c2 = c0 + строки[0].length - 1;
  диапазон(ОБЛАСТЬ(r0, c0, r2, c2)).записать(строки);
  for(let c = c0; c <= c2; c++) клетка(r0, c).стиль = {b: 1, fill: '#e7eef9', align: 'center', wrap: 1};
  for(let r = r0 + 1; r <= r2; r++) клетка(r, c0).стиль = {b: 1, fill: '#f3f6fb'};
  const ф1 = формат(опр.вход1), фц = формат(цели[0]);
  try {
    const л = Api.GetActiveSheet();
    if(ф1) оформитьОбласть(лист(), r0 + 1, c0, r2, c0, {fmt: ф1});
    if(опр.вид === 2){ const ф2 = формат(опр.вход2); if(ф2) оформитьОбласть(лист(), r0, c0 + 1, r0, c2, {fmt: ф2}); }
    if(фц) оформитьОбласть(лист(), r0 + 1, c0 + 1, r2, c2, {fmt: фц});
    if(опр.вид === 2 && r2 > r0 + 1) л.GetRange(ОБЛАСТЬ(r0 + 1, c0 + 1, r2, c2)).GetFormatConditions().AddColorScale(3);
  } catch(e){ сообщить('формат: ' + e.message); }
  панель.сообщение('Таблица ' + (строки.length - 1) + '×' + (строки[0].length - 1) + ' от ' + опр.куда + ': ' + n + ' прогонов модели за ' + (Date.now() - t0) + ' мс. Значения — числа; модель поменяется — «Пересчитать таблицы».');
}
async function _ПересчитатьТаблицы(){
  const все = лист().память('таблицы-подстановки') || [];
