/* ================= поиск решения ================= */
let решение = null;
function разобратьОграничения(текст){
  const out = [], целые = [], двоичные = [];
  String(текст || '').split(/\n/).map(s => s.trim()).filter(s => s && !s.startsWith('#') && !s.startsWith('//')).forEach(стр => {
    const ц = стр.match(/^(.+?)\s+(цел\S*|integer|int|бин\S*|двоичн\S*|binary|bin)$/i);
    if(ц){ const к = клетки(ц[1]); if(/^(бин|двоичн|binary|bin)/i.test(ц[2])) двоичные.push(...к); else целые.push(...к); return; }
    const m = стр.match(/^(.+?)\s*(<=|>=|=<|=>|≤|≥|==|=)\s*(.+)$/);
    if(!m) throw new Error('Ограничение «' + стр + '» не понял: пишите «B2:D2 >= 0», «F10 <= 100», «B2:D2 цел» или «B2 бин»');
    const знак = ({'<=': '<=', '=<': '<=', '≤': '<=', '>=': '>=', '=>': '>=', '≥': '>=', '=': '=', '==': '='})[m[2]];
    const лев = клетки(m[1]);
    const пр = m[3].trim(), прЧ = текстЧисло(пр);
    const прав = isFinite(прЧ) ? лев.map(() => прЧ) : (() => { const к = клетки(пр); if(к.length === 1) return лев.map(() => к[0]); if(к.length !== лев.length) throw new Error('В «' + стр + '» справа и слева разное число клеток'); return к; })();
    лев.forEach((a, i) => out.push({лев: a, знак, прав: прав[i], текст: стр}));
  });
  return {строки: out, целые, двоичные};
}
