      for(const a of огр.двоичные) строки.push({a: пер.map((_, i) => i === индекс.get(a) ? 1 : 0), знак: '<=', b: 1});
      const з = {c: вид === 'Значение' ? пер.map(() => 0) : коэф[0], max: вид !== 'Минимум', строки: строки.slice(), свободные: п.неотриц === false ? пер.map((_, i) => i) : []};
      if(вид === 'Значение') з.строки.push({a: коэф[0], знак: '=', b: нужно - пост(0)});
      const р2 = цел.size ? ЛП.целочисленно(з, [...цел], {время: 25000}) : ЛП.решить(з);
      ответ = {метод: цел.size ? 'целочисленная линейная (ветви и границы, узлов ' + р2.узлов + ')' : 'линейная (симплекс-метод)', статус: р2.статус, x: р2.x};
    } else ответ = await нелинейно({x0, пер, цели, огрИ, вид, нужно, набор, неотриц: п.неотриц !== false});
    if(!ответ.x){
      const слова = {'несовместна': 'Ограничения несовместны: нет значений, при которых выполнены все условия.', 'неограничена': 'Цель не ограничена: её можно увеличивать (уменьшать) бесконечно — не хватает ограничения.', 'предел': 'Поиск остановлен на пределе времени, допустимого решения не найдено.'};
      скажи([{текст: 'Решение не найдено. ', жирный: true, цвет: '#c92a2a'}, {текст: (слова[ответ.статус] || ответ.статус) + ' Метод: ' + ответ.метод + '. Книга не менялась.'}]);
      панель.список('решение', []);
      return;
    }
    /* честная проверка: прогон модели с найденными значениями */
    const x = ответ.x.map(v => Math.abs(v - Math.round(v)) < 1e-9 ? Math.round(v) : +v.toPrecision(12));
    const [пр] = await прогон([набор(x)], цели);
    const нарушения = [];
    огрИ.forEach(о => { const л = числом(пр[о.л]), r = о.п >= 0 ? числом(пр[о.п]) : о.прав, доп = 1e-6 * (1 + Math.abs(r));
      if(!(о.знак === '<=' ? л <= r + доп : о.знак === '>=' ? л >= r - доп : Math.abs(л - r) <= доп)) нарушения.push(о.лев + ' ' + о.знак + ' ' + чсл(r) + ' (сейчас ' + чсл(л) + ')'); });
    решение = {пер, x, цель, значение: числом(пр[0]), огрИ, пр, цели, x0, вид, метод: ответ.метод, статус: ответ.статус, нарушения};
    const заголовок = нарушения.length ? [{текст: 'Найдено, но проверка не прошла: ', жирный: true, цвет: '#c92a2a'}, {текст: 'нарушены ' + нарушения.slice(0, 3).join('; ') + '. '}]
      : ответ.статус === 'оптимум' ? [{текст: линейна ? 'Найдено оптимальное решение. ' : 'Найдено решение. ', жирный: true, цвет: '#2b8a3e'}]
      : ответ.статус === 'предел' ? [{текст: 'Лучшее найденное за отведённое время (оптимальность не доказана). ', жирный: true, цвет: '#e67700'}]
      : [{текст: 'Найдено приближённо. ', жирный: true, цвет: '#e67700'}];
    скажи(заголовок.concat([{текст: 'Цель ' + цель + ' = ' + чсл(решение.значение) + '. Метод: ' + ответ.метод + (линейна ? '' : ' — местный оптимум, без гарантии лучшего') + '. ' + (Date.now() - t0) + ' мс. Книга не менялась: «Оставить решение» запишет значения.'}]));
    панель.список('решение', пер.map((a, i) => [подпись(a, пер.length > 1) === a ? a : подпись(a, пер.length > 1) + ' (' + a + ')', чсл(x[i])]).concat([['Цель ' + цель, чсл(решение.значение)]]));
  } catch(e){ скажи([{текст: e.message, цвет: '#c92a2a'}]); }
}
/* нелинейная модель: спуск по оценке градиента со штрафом за нарушения и поиском шага — пачками */
async function нелинейно(м){
  const {пер, цели, огрИ, вид, нужно, набор, неотриц} = м, n = пер.length;
  const знак = вид === 'Минимум' ? 1 : -1;
  let μ = 10;
  const штрафная = ряд => {
    let v = вид === 'Значение' ? Math.pow(числом(ряд[0]) - нужно, 2) : знак * числом(ряд[0]), s = 0;
    for(const о of огрИ){ const л = числом(ряд[о.л]), r = о.п >= 0 ? числом(ряд[о.п]) : о.прав; const d = о.знак === '<=' ? Math.max(0, л - r) : о.знак === '>=' ? Math.max(0, r - л) : Math.abs(л - r); s += d * d; }
    return isFinite(v) && isFinite(s) ? v + μ * s : Infinity;
  };
  const огр = x => неотриц ? x.map(v => Math.max(0, v)) : x;
  let x = огр(м.x0.slice()), fx = штрафная((await прогон([набор(x)], цели))[0]), шаг = 1;
  for(let it = 0; it < 300; it++){
    const h = x.map(v => 1e-6 * Math.max(1, Math.abs(v)));
    const точки = [x].concat(x.map((_, i) => { const y = x.slice(); y[i] += h[i]; return y; }));
    const р = await прогон(точки.map(набор), цели);
    fx = штрафная(р[0]);
    const g = x.map((_, i) => (штрафная(р[1 + i]) - fx) / h[i]);
    const нг = Math.hypot(...g);
    if(!isFinite(нг) || нг < 1e-12) break;
    const масштаб = Math.max(1, Math.hypot(...x));
    const пробы = []; for(let k = 8; k >= -30; k--) пробы.push(огр(x.map((v, i) => v - Math.pow(2, k) * масштаб * g[i] / нг)));
    const р2 = await прогон(пробы.map(набор), цели);
    let лучш = -1, fb = fx;
    р2.forEach((ряд, k) => { const f = штрафная(ряд); if(f < fb - 1e-12 * (1 + Math.abs(fb))){ fb = f; лучш = k; } });
    if(лучш < 0){ if(μ < 1e8){ μ *= 10; continue; } break; }
    const старое = fx; x = пробы[лучш]; fx = fb;
    if(Math.abs(старое - fx) < 1e-11 * (1 + Math.abs(fx)) && it > 20){ if(μ < 1e8) μ *= 10; else break; }
    if(it % 25 === 24 && μ < 1e8) μ *= 10;
  }
  return {метод: 'нелинейная (градиентный спуск со штрафами)', статус: 'приближённо', x};
}
function _ОставитьРешение(){
  if(!решение){ панель.сообщение('Сначала «Найти решение»'); return; }
  решение.пер.forEach((a, i) => { const а = разобратьАдрес(a); (а.лист ? лист(а.лист) : лист()).ячейка(а.r1 + 1, а.c1 + 1).значение = решение.x[i]; });
  панель.сообщение('Значения ' + решение.пер.length + ' клеток записаны одной операцией — «Отменить» вернёт прежние');
}
async function _ОтчётРешения(){
  if(!решение){ панель.сообщение('Сначала «Найти решение»'); return; }
  const р = решение, строки = [['Отчёт поиска решения', '', '', '', ''], ['Метод', р.метод, '', '', ''], ['Итог', р.нарушения.length ? 'проверка не прошла' : р.статус, '', '', ''], ['', '', '', '', ''],
    ['Цель', 'Клетка', 'Было', 'Стало', ''], [подпись(р.цель), р.цель, числом(значение(р.цель)), р.значение, р.вид], ['', '', '', '', ''], ['Переменные', 'Клетка', 'Было', 'Стало', '']];
  р.пер.forEach((a, i) => строки.push([подпись(a, true), a, р.x0[i], р.x[i], '']));
  строки.push(['', '', '', '', ''], ['Ограничения', 'Клетка', 'Значение', 'Условие', 'Запас']);
  р.огрИ.forEach(о => { const л = числом(р.пр[о.л]), r = о.п >= 0 ? числом(р.пр[о.п]) : о.прав; const запас = о.знак === '<=' ? r - л : о.знак === '>=' ? л - r : 0;
    строки.push([подпись(о.лев), о.лев, л, о.знак + ' ' + чсл(r), Math.abs(запас) < 1e-9 ? 'связывающее' : +запас.toPrecision(10)]); });
  const ИМЯ = 'Отчёт поиска решения';
  const л = await книга.черновик(ИМЯ);
  л.диапазон(ОБЛАСТЬ(0, 0, строки.length - 1, 4)).записать(строки);
  л.ячейка(1, 1).стиль = {b: 1, sz: 13};
  строки.forEach((s, i) => { if(['Цель', 'Переменные', 'Ограничения'].includes(s[0])) for(let c = 0; c < 5; c++) л.ячейка(i + 1, c + 1).стиль = {b: 1, fill: '#e7eef9'}; });
  try { Api.GetSheet(ИМЯ).GetRange('A1:A1').SetColumnWidth(30); Api.GetSheet(ИМЯ).GetRange('B1:E1').SetColumnWidth(16); } catch(e){}
  книга.выделить(ИМЯ + '!A1');
  панель.сообщение('Отчёт — на черновом листе «' + ИМЯ + '» (✓ на ярлычке — оставить в книге)');
}
